// Свободные слоты: единый источник — canonSlots; отдаём только свободные в окне 12 рабочих дней.
const staticData = $getWorkflowStaticData('global');
staticData.bookings = staticData.bookings || {};
const today = new Date(Date.now() + 7 * 3600 * 1000).toISOString().slice(0, 10);
for (const k of Object.keys(staticData.bookings)) {
  if (k.slice(0, 10) < today) delete staticData.bookings[k];
}
// === ЕДИНЫЙ ИСТОЧНИК СЛОТОВ: demo-10 «Слоты» и «Бронь» (менять синхронно, см. tests/test_workflows.py) ===
const SLOT_DAYS = 12; // рабочих дней вперёд
const SLOT_TIMES = [['10:00', 'утро'], ['14:00', 'день']];
function canonSlots(booked) {
  const out = [];
  const d = new Date(Date.now() + 7 * 3600 * 1000); // Барнаул = UTC+7
  let made = 0;
  while (made < SLOT_DAYS) {
    d.setDate(d.getDate() + 1);
    const dow = d.getDay();
    if (dow === 0 || dow === 6) continue;
    const day = d.toISOString().slice(0, 10);
    for (const [h, label] of SLOT_TIMES) {
      const id = day + '-' + h.replace(':', '');
      out.push({ id, label, start: day + ' ' + h + ' (' + label + ')', tz: 'Asia/Barnaul', booked: !!booked[id] });
    }
    made += 1;
  }
  return out;
}
// === КОНЕЦ ЕДИНОГО ИСТОЧНИКА ===
const slots = canonSlots(staticData.bookings)
  .filter((s) => !s.booked)
  .map((s) => ({ id: s.id, label: s.label, start: s.start, tz: s.tz }));
return [{ json: { ok: true, slots } }];

function resolveUser(body) {
  const crypto = require('crypto');
  try {
    if (body.init_data) {
      // ручной разбор строки initData (без стандартного URL-парсера:
      // в песочнице Code node он недоступен);
      // data_check_string строится из СЫРЫХ значений, как требует Telegram
      const raw = String(body.init_data);
      let hash = '';
      const pairs = [];
      for (const part of raw.split('&')) {
        const eq = part.indexOf('=');
        if (eq < 0) continue;
        const k = part.slice(0, eq);
        const v = part.slice(eq + 1);
        if (k === 'hash') { hash = v; continue; }
        if (k === 'signature') continue;
        pairs.push([k, v]);
      }
      const dcs = pairs.map(([k, v]) => k + '=' + v).sort().join('&');
      const secret = crypto.createHmac('sha256', 'WebAppData').update('__BOT_TOKEN__').digest();
      const calc = crypto.createHmac('sha256', secret).update(dcs).digest('hex');
      if (!hash || calc !== hash) return null;
      const uv = (pairs.find(([k]) => k === 'user') || [])[1] || '{}';
      const u = JSON.parse(decodeURIComponent(uv));
      return u.username ? '@' + String(u.username) : (u.id ? String(u.id) : null);
    }
    if (body.user && body.sig) {
      const calc = crypto.createHmac('sha256', '__SIGN_SECRET__').update(String(body.user)).digest('hex');
      return calc === String(body.sig) ? String(body.user) : null;
    }
  } catch (e) {
    return null;
  }
  return null;
}
